<template>
 <section aria-label="明确有限病例统计场景入口">
  <p>请从目录选择统计场景，核对比较范围、时间窗口和显著性阈值后再计算。</p>
  <p v-if="!valid" role="alert">场景引用包含空值、外域字段或不是规范UUID，已清除旧选择。</p>
  <template v-if="allowed"><details><summary>使用已知场景标识</summary><el-form-item label="场景UUID"><el-input :model-value="enteredRef" aria-label="已提供的统计场景引用" placeholder="粘贴已获授权的场景UUID" @update:model-value="entryChanged"/></el-form-item></details><template v-if="valid"><el-button v-if="pending" :disabled="busy" @click="refresh">核对明确统计场景引用</el-button><el-button v-if="selected" @click="clear">清除统计场景选择</el-button><p v-if="error" role="alert">{{error}}</p><p v-if="selected" aria-label="已选择完整统计场景">已明确场景{{selected.scenario_id}}；尚未创建任务。</p><InfectionSources :key="childKey" :active="active" :governance="false" @select="select" @invalidate="unavailable" @source-changed="clear"/></template></template>
  <p v-else-if="!allowed">当前身份不能读取或选择完整病例统计场景。</p>
 </section>
</template>
<script setup>
import{computed,onBeforeUnmount,onDeactivated,ref,watch}from'vue';import{useStore}from'vuex';import InfectionSources from'./InfectionSources.vue';import{getInfectionScenario,infectionReferencesValid}from'@/api/ai/infectionClusterSources';import{canonical,keys,uuid,verifyScenario}from'@/api/ai/infectionClusterProofs';
const props=defineProps({initialReferences:{default:null},active:{type:Boolean,default:true}}),emit=defineEmits(['scope-change','selection','availability','invalidate']),store=useStore(),selected=ref(null),busy=ref(false),error=ref(''),childKey=ref(0),enteredRef=ref('');let epoch=0;
const valid=computed(()=>(props.initialReferences===null||keys(props.initialReferences,[])||infectionReferencesValid(props.initialReferences))&&(enteredRef.value===''||uuid(enteredRef.value))),pending=computed(()=>enteredRef.value|| (infectionReferencesValid(props.initialReferences)?props.initialReferences.infection_cluster_scenario_id:null)),identity=computed(()=>canonical({refs:props.initialReferences,active:props.active,token:store.state.user?.accessToken??null,name:store.state.user?.username??null,roles:store.getters['user/permissions']??store.state.user?.permissions??[]})),allowed=computed(()=>props.active&&!!store.state.user?.accessToken&&(store.getters['user/permissions']??store.state.user?.permissions??[]).some(r=>['super_admin','admin','director'].includes(r)));
function unavailable(){++epoch;selected.value=null;busy.value=false;error.value='';emit('availability',false);emit('selection',{});emit('invalidate');}
function clear(){enteredRef.value='';unavailable();childKey.value++;}
function entryChanged(v){enteredRef.value=v;unavailable();childKey.value++;}
async function select(row){if(!allowed.value||!valid.value)return;unavailable();const t=++epoch,i=identity.value,current=()=>t===epoch&&identity.value===i&&allowed.value&&valid.value;busy.value=true;try{if(!await verifyScenario(row,{requirePublished:true,current})||!current())throw Error();selected.value={scenario_id:row.scenario_id,content_hash:row.content_hash,governance_hash:row.governance_hash,source_binding:JSON.parse(canonical(row.payload.source_binding)),plan_hash:row.payload.plan_hash,recipe_hash:row.payload.recipe_hash,implementation_hash:row.payload.implementation_hash};emit('selection',{infection_cluster_scenario_id:row.scenario_id});emit('availability',true);}catch{if(current())error.value='完整场景或当前来源无法核对，请显式重新读取。';}finally{if(current())busy.value=false;}}
async function refresh(){if(!pending.value||!allowed.value||!valid.value)return;unavailable();const t=++epoch,i=identity.value,id=pending.value;busy.value=true;try{const v=(await getInfectionScenario(id)).data;if(t!==epoch||identity.value!==i)return;if(v.scenario_id!==id)throw Error();await select(v);}catch{if(t===epoch&&identity.value===i){error.value='当前场景或患者目的许可已失效，旧选择未恢复。';busy.value=false;}}}
watch(identity,()=>{clear();emit('scope-change');},{immediate:true,flush:'sync'});onDeactivated(clear);onBeforeUnmount(()=>{++epoch;selected.value=null;});
</script>
